"""Basic English lessons for ZYGON: greetings, small talk, who it is, vocabulary facts, grammar, plus simple reading text and a test set of wordings it is NOT taught.
Written by Claude for this project. A lesson = several ways of saying something (wordings) hooked to one or more replies.
"""
import itertools

LESSONS = []          # (category, [wordings], [replies])
READING = []          # plain text for the wheels (simple English)
TESTS = []            # (wording never taught, category it should land in)


def L(cat, utts, replies):
    LESSONS.append((cat, utts, replies if isinstance(replies, list) else [replies]))


