# ------------------------------------------------------------------ grammar: one definition, many ways of asking
def G(cat, term, plural, answer, article="a", extra=()):
    forms = [f"what is {article} {term}", f"what is {term}", f"what is the {term}", f"what are {plural}", f"what are the {plural}", f"define {term}", f"define {article} {term}", f"explain {term}", f"explain {plural}", f"explain {article} {term}",
             f"tell me about {plural}", f"tell me about {term}", f"tell me what {article} {term} is", f"{term}", f"{plural}", f"{term} meaning", f"what does {term} mean", f"what do you mean by {term}", f"meaning of {term}", f"definition of {term}",
             f"give me the definition of {term}", f"i dont understand {plural}", f"can you explain {plural}", f"can you explain {term}", f"what is the meaning of {term}", f"whats {article} {term}", f"whats {term}", f"how do you define {term}",
             f"teach me {plural}", f"teach me about {plural}", f"what is the definition of {term}", f"describe {article} {term}", f"help me understand {plural}", f"what does {article} {term} mean", f"i want to learn about {plural}"]
    L(cat, list(dict.fromkeys(forms + list(extra))), answer)


def GA(cat, term, plural, answer):
    G(cat, term, plural, answer, "an" if term[0] in "aeiou" else "a")


